window.addEventListener('hashchange',()=>{if($('#dialog').open)closeDialog();state.selected.clear();render();window.scrollTo(0,0)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search input')?.focus()}if(e.key==='Escape')$('#sidebar')?.classList.remove('open')});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
render();
